def recur(start: str, rule: str, count: int) -> list[str]:
    from datetime import date, timedelta
    import calendar

    y, m, d = (int(p) for p in start.split("-"))
    start_date = date(y, m, d)
    parts = rule.split(" ")
    kind = parts[0]
    k = int(parts[1])
    codes = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}
    out = []

    def add(dt):
        if dt is not None and dt >= start_date:
            out.append(dt.isoformat())

    if kind == "DAILY":
        cur = start_date
        while len(out) < count:
            out.append(cur.isoformat())
            cur += timedelta(days=k)
        return out

    if kind == "WEEKLY":
        wanted = {codes[c] for c in parts[2].split(",")}
        monday0 = start_date - timedelta(days=start_date.weekday())
        w = 0
        while len(out) < count:
            monday = monday0 + timedelta(weeks=w)
            for wd in range(7):
                if wd in wanted:
                    add(monday + timedelta(days=wd))
                    if len(out) == count:
                        return out
            w += k
        return out

    if kind == "MONTHLY" and len(parts) == 3:
        day_spec = int(parts[2])
        mi = 0
        while len(out) < count:
            yy = start_date.year + (start_date.month - 1 + mi) // 12
            mm = (start_date.month - 1 + mi) % 12 + 1
            last = calendar.monthrange(yy, mm)[1]
            if day_spec == -1:
                add(date(yy, mm, last))
            elif day_spec <= last:
                add(date(yy, mm, day_spec))
            mi += k
        return out

    if kind == "MONTHLY":
        n = int(parts[2])
        wd = codes[parts[3]]
        mi = 0
        while len(out) < count:
            yy = start_date.year + (start_date.month - 1 + mi) // 12
            mm = (start_date.month - 1 + mi) % 12 + 1
            if n == -1:
                last_day = calendar.monthrange(yy, mm)[1]
                last = date(yy, mm, last_day)
                add(last - timedelta(days=(last.weekday() - wd) % 7))
            else:
                first = date(yy, mm, 1)
                first_wd = first + timedelta(days=(wd - first.weekday()) % 7)
                dt = first_wd + timedelta(days=7 * (n - 1))
                if dt.month == mm:
                    add(dt)
            mi += k
        return out

    mm_s, dd_s = parts[2].split("-")
    mm, dd = int(mm_s), int(dd_s)
    yi = 0
    while len(out) < count:
        yy = start_date.year + yi
        try:
            add(date(yy, mm, dd))
        except ValueError:
            pass
        yi += k
    return out
